    virtualKB::Keyboard *kb = ServiceLocator::getKeyboard();
    virtualKB::NumberKeyboard *numkb = ServiceLocator::getNumberKeyboard();

    if(this->inputMethodHints() & Qt::ImhPreferNumbers){
        // qDebug() << "数字键盘";
        numkb->show();
    }else{
        // qDebug() << "非数字键盘";
        kb->move(this->mapToGlobal(QPoint(0,0)).rx()+255,this->mapToGlobal(QPoint(0,0)).ry()+160);
        kb->show();
    }
    QPlainTextEdit::focusInEvent(e);
}

void CodeEditor::focusOutEvent(QFocusEvent *e)
{
    virtualKB::Keyboard *kb = ServiceLocator::getKeyboard();
    virtualKB::NumberKeyboard *numkb = ServiceLocator::getNumberKeyboard();

    kb->close();
    numkb->close();
    QPlainTextEdit::focusOutEvent(e);
}


