package com.meelive.ingkee.business.audio.audience.ui

import android.os.Looper
import android.os.MessageQueue
import android.os.SystemClock
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

/***
 * 有超时功能的IdleHandler事件队列
 * idleHandler事件在低端机型可能很久才能执行到，这个任务可以加一个超时时间，超时后直接自动执行
 */
class UITaskQueue {
    private val idleHandler = object : MessageQueue.IdleHandler {
        override fun queueIdle(): Boolean {
            synchronized(taskMap) {
                performTasks()
                return if (taskMap.isEmpty()) {
                    false
                } else {
                    // 只要还有任务，就继续注册IdleHandler
                    true
                }
            }
        }
    }

    // 使用ConcurrentHashMap提高并发访问时的性能
    private val taskMap = ConcurrentHashMap<UUID, Pair<Runnable, Long>>()

    var startTime: Long = 0

    fun startLinster(){
        startTime = SystemClock.uptimeMillis()
        Looper.myQueue().addIdleHandler(idleHandler)
    }

    fun addTask(task: Runnable, timeoutMillis: Long) {
        val taskId = UUID.randomUUID()
        taskMap[taskId] = task to timeoutMillis

        // 检查是否需要移除IdleHandler，如果任务队列为空
        removeIdleHandlerIfEmpty()
    }

    private fun performTasks() {
        taskMap.forEach { (taskId, pair) ->
            pair.first.run()
            taskMap.remove(taskId)
        }
    }

    fun clear(){
        taskMap.clear()
        Looper.myQueue().removeIdleHandler(idleHandler)
    }

    private fun removeIdleHandlerIfEmpty() {
        if (taskMap.isEmpty()) {
            Looper.myQueue().removeIdleHandler(idleHandler)
        }
    }

    fun removeTask(taskId: UUID) {
        synchronized(taskMap) {
            taskMap.remove(taskId)
            removeIdleHandlerIfEmpty()
        }
    }
}
