while(my $line = <GFF>){
	chomp $line ;
	next if $line =~ /^#/;
	my @t = split /\t/, $line;
	next unless  ( @t == 9);

	my $id1 = "NA";
	my $id2 = "NA";
	if($t[8] =~ /ID=([^;]+)/){
		$id1 = $1;
	}

	if($t[8] =~ /Parent=([^;]+)/){
		$id2 = $1;
	}

	my $out = $line ;
	my $flag = 0;
	if($t[2] eq "gene"){
		next unless exists $gene2mRNA{$id1}; 
		$flag = 1;
	}

	if($t[2] eq "mRNA"){
		next unless exists $lmRNA{$id1};
		$flag = 1;
	}

	if($t[2] =~ /CDS/i || $t[2] =~ /exon/i || $t[2] =~ /UTR/i ){
		next unless exists $lmRNA{$id2};
		$flag = 1;
	}
	if($flag == 1){	
		print O2 "$out\n";
	}
}
